#define main original_tool_main
#include "test-painter-mypaint-tool.cpp"
#undef main
static void trace(bool settings,bool floating){Scene s;g_object_set(s.options,"non-incremental",floating,"stroke-opacity",.37,nullptr);s.motion(false);auto initial=s.pixels();s.press();for(int i=0;i<180;++i){if(settings&&i==60)g_object_set(s.options,"radius-logarithmic",2.0,nullptr);if(settings&&i==100)g_object_set(s.options,"smudge",.4,nullptr);s.coords.x=24+(i%80);s.coords.y=24+((i/80)*24);s.motion(true,100);g_print("ACTIVE %d %d %d %d\n",settings,floating,i,gimp_tool_control_is_active(s.tool->control));auto p=s.pixels();auto*h=g_compute_checksum_for_data(G_CHECKSUM_SHA256,p.data(),p.size());g_print("PIX %d %d %d %s\n",settings,floating,i,h);g_free(h);}if(gimp_tool_control_is_active(s.tool->control))s.release();auto after=s.pixels();auto*h=g_compute_checksum_for_data(G_CHECKSUM_SHA256,after.data(),after.size());g_print("FINAL %d %d %s depth=%d\n",settings,floating,h,s.depth());g_free(h);g_assert_true(after!=initial);}
static void traces(){for(bool settings:{false,true})for(bool floating:{false,true})trace(settings,floating);}
int main(int argc,char**argv){g_test_init(&argc,&argv,nullptr);gimp_test_utils_set_gimp3_directory("GIMP_TESTING_ABS_TOP_SRCDIR","app/tests/gimpdir");gimp_test_utils_setup_menus_path();gimp=gimp_init_for_gui_testing(TRUE);g_object_set(gimp->config,"painter-canvas-ui",TRUE,nullptr);g_test_add_func("/physical-gesture/trace",traces);g_application_run(gimp->app,0,nullptr);int result=gimp_core_app_get_exit_status(GIMP_CORE_APP(gimp->app));g_application_quit(G_APPLICATION(gimp->app));g_clear_object(&gimp->app);return result;}
